BEGIN;

CREATE OR REPLACE FUNCTION refs_read_ai_fixed_asset_depreciation_source(p_tenant uuid,p_entity uuid,p_period uuid) RETURNS SETOF jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM refs_assert_scope(p_tenant,p_entity,'AI.ANALYSIS.EXPLAIN');RETURN QUERY WITH p AS (SELECT period_id,period_code,starts_on,ends_on FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND ledger_code='PRIMARY'),calc AS (SELECT r.*,p.*,round((r.cost_basis-r.salvage_value)/r.useful_life_months,4) monthly,greatest(0,((extract(year from p.ends_on)::int-extract(year from r.placed_in_service_date)::int)*12+extract(month from p.ends_on)::int-extract(month from r.placed_in_service_date)::int+1)) elapsed FROM fixed_asset_register_evidence r CROSS JOIN p WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.status='ACTIVE') SELECT jsonb_build_object('period_id',period_id,'period_code',period_code,'fixed_asset_register_evidence_id',fixed_asset_register_evidence_id,'source_document_id',source_document_id,'source_payload_hash',source_payload_hash,'capitalization_proposal_id',capitalization_proposal_id,'register_evidence_hash',register_evidence_hash,'asset_tag',asset_tag,'asset_class',asset_class,'depreciation_method',depreciation_method,'depreciation_convention',depreciation_convention,'placed_in_service_date',to_char(placed_in_service_date,'YYYY-MM-DD'),'useful_life_months',useful_life_months,'currency',currency,'cost_basis',to_char(cost_basis,'FM999999999999990.0000'),'salvage_value',to_char(salvage_value,'FM999999999999990.0000'),'depreciable_basis',to_char(cost_basis-salvage_value,'FM999999999999990.0000'),'expected_period_depreciation',to_char(CASE WHEN starts_on>=(placed_in_service_date-date_part('day',placed_in_service_date)::int+1) AND elapsed BETWEEN 1 AND useful_life_months THEN (CASE WHEN elapsed>=useful_life_months THEN cost_basis-salvage_value ELSE least(cost_basis-salvage_value,monthly*elapsed) END)-(least(cost_basis-salvage_value,monthly*greatest(0,elapsed-1))) ELSE 0 END,'FM999999999999990.0000'),'expected_accumulated_depreciation',to_char((CASE WHEN elapsed>=useful_life_months THEN cost_basis-salvage_value ELSE least(cost_basis-salvage_value,monthly*elapsed) END),'FM999999999999990.0000'),'expected_net_book_value',to_char(cost_basis-(CASE WHEN elapsed>=useful_life_months THEN cost_basis-salvage_value ELSE least(cost_basis-salvage_value,monthly*elapsed) END),'FM999999999999990.0000'),'asset_account_code',asset_account_code,'accumulated_depreciation_account_code',accumulated_depreciation_account_code,'depreciation_expense_account_code',depreciation_expense_account_code,'status',status) FROM calc ORDER BY asset_tag;END;$$;
REVOKE EXECUTE ON FUNCTION refs_read_ai_fixed_asset_depreciation_source(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION refs_read_ai_fixed_asset_depreciation_source(uuid,uuid,uuid) TO refs_app;

COMMIT;
